<template>
  <div class="today-page space-y-7">
    <section class="flex flex-wrap items-end justify-between gap-5"><div><p class="eyebrow">{{ dateLabel }}</p><h1 class="page-title">Chào {{ user?.fullName || user?.username || 'bạn' }}<span class="text-indigo-500">.</span></h1><p class="page-description">{{ pending.length ? `Bạn còn ${pending.length} việc cần hoàn thành. Cùng bắt đầu nhé.` : 'Một ngày mới, mọi thứ trong tầm tay của bạn.' }}</p></div><div class="flex gap-2"><button class="secondary-button" @click="hidden=!hidden"><span class="material-symbols-rounded">{{ hidden?'visibility':'visibility_off' }}</span>{{ hidden?'Hiện số tiền':'Ẩn số tiền' }}</button><button class="primary-button" @click="$emit('switch-tab','finance')"><span class="material-symbols-rounded">add</span>Ghi thu chi</button></div></section>
    <div class="overview-grid"><section class="balance-card"><div class="flex justify-between items-center"><span class="text-sm text-indigo-100">Số dư hiện có</span><span class="material-symbols-rounded text-indigo-200">account_balance_wallet</span></div><div class="balance-number">{{ money(balance) }}</div><div class="balance-footer"><span>{{ wallets.length }} ví đang quản lý</span><button @click="$emit('switch-tab','finance')">Xem ví <span aria-hidden="true">↗</span></button></div></section><button class="metric-card" @click="$emit('switch-tab','debts')"><span class="metric-icon bg-rose-50 text-rose-500 material-symbols-rounded">receipt_long</span><span class="text-sm text-slate-500">Nợ chưa thanh toán</span><strong>{{ money(unpaidTotal) }}</strong><small>{{ unpaid.length }} khoản cần theo dõi <span>→</span></small></button><button class="metric-card" @click="$emit('switch-tab','tasks')"><span class="metric-icon bg-amber-50 text-amber-600 material-symbols-rounded">checklist</span><span class="text-sm text-slate-500">Công việc đang chờ</span><strong>{{ pending.length }} <span class="text-base font-normal text-slate-400">việc</span></strong><small>{{ overdue.length ? `${overdue.length} việc đã quá hạn` : 'Sắp xếp từng việc, nhẹ đầu hơn' }} <span>→</span></small></button></div>
    <section v-if="priority.length" class="surface overflow-hidden"><div class="section-header"><div><h2 class="section-title">Cần chú ý</h2><p class="text-sm text-slate-500 mt-1">Những khoản thanh toán nên kiểm tra trước.</p></div><button class="text-link" @click="$emit('switch-tab','debts')">Tất cả khoản nợ ↗</button></div><button v-for="debt in priority" :key="debt.id" class="attention-row" @click="$emit('switch-tab','debts')"><span :class="['row-icon material-symbols-rounded',isOverdue(debt.dueDate)?'text-rose-500 bg-rose-50':'text-amber-600 bg-amber-50']">{{ isOverdue(debt.dueDate)?'priority_high':'schedule' }}</span><span class="flex-1 min-w-0 text-left"><strong class="block text-sm text-slate-800 truncate">{{ debt.title }}</strong><small class="text-slate-500">{{ isOverdue(debt.dueDate)?'Đã quá hạn':'Đến hạn' }} · {{ shortDate(debt.dueDate) }}</small></span><strong class="text-sm tabular-nums">{{ money(Math.max(0,Number(debt.totalAmount)-Number(debt.paidAmount||0))) }}</strong><span class="material-symbols-rounded text-slate-300 text-lg">chevron_right</span></button></section>
    <div class="today-grid"><section class="surface"><div class="section-header"><div class="flex items-center gap-3"><span class="material-symbols-rounded text-indigo-500">calendar_today</span><h2 class="section-title">Lịch hôm nay</h2><span class="small-count">{{ todayEvents.length }}</span></div><button class="text-link" @click="$emit('switch-tab','calendar')">Mở lịch ↗</button></div><div v-if="!todayEvents.length" class="empty-state"><span class="material-symbols-rounded">event_available</span><h3>Hôm nay lịch đang trống</h3><p>Dành một khoảng thời gian cho điều bạn muốn làm.</p><button class="text-link" @click="$emit('switch-tab','calendar')">+ Thêm lịch hẹn</button></div><div v-else class="px-5 pb-4"><div v-for="event in todayEvents" :key="event.id" class="schedule-row"><span class="schedule-time">{{ time(event.startTime) }}</span><div><strong class="text-sm">{{ event.title }}</strong><p class="text-xs text-slate-500 mt-1">{{ event.category }} · đến {{ time(event.endTime) }}</p></div></div></div></section><section class="surface"><div class="section-header"><div class="flex items-center gap-3"><span class="material-symbols-rounded text-indigo-500">task_alt</span><h2 class="section-title">Việc tiếp theo</h2></div><button class="text-link" @click="$emit('switch-tab','tasks')">Tất cả ↗</button></div><div v-if="!pending.length" class="empty-state"><span class="material-symbols-rounded">check_circle</span><h3>Bạn đã hoàn thành mọi việc</h3><p>Thêm kế hoạch tiếp theo khi bạn sẵn sàng.</p><button class="text-link" @click="$emit('switch-tab','tasks')">+ Thêm công việc</button></div><div v-else class="px-5 pb-4"><div v-for="task in pending.slice(0,5)" :key="task.id" class="task-row"><button class="task-check" :aria-label="`Hoàn thành ${task.title}`" @click="$emit('toggle-task',task.id)"><span class="material-symbols-rounded">check</span></button><span class="flex-1 text-sm">{{ task.title }}</span><span v-if="task.dueDate" :class="['text-xs',isOverdue(task.dueDate)?'text-rose-600':'text-slate-400']">{{ shortDate(task.dueDate) }}</span></div></div></section></div>
    <p class="text-xs text-slate-400 text-center">Personal OS · Một nơi cho những điều quan trọng.</p>
  </div>
</template>
<script setup>
import {computed,ref,onMounted,onUnmounted} from 'vue';
const props=defineProps({user:Object,wallets:{type:Array,default:()=>[]},debts:{type:Array,default:()=>[]},events:{type:Array,default:()=>[]},tasks:{type:Array,default:()=>[]},notes:{type:Array,default:()=>[]}});
defineEmits(['switch-tab','toggle-task','refresh-all']);
const now=ref(new Date()),hidden=ref(false);let timer;
onMounted(()=>{timer=setInterval(()=>{now.value=new Date();},60000);});onUnmounted(()=>clearInterval(timer));
const dateKey=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const dateLabel=computed(()=>now.value.toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}));
const balance=computed(()=>props.wallets.reduce((s,w)=>s+Number(w.balance||0),0));
const unpaid=computed(()=>props.debts.filter(x=>x.recordType==='DEBT'&&!x.isCompleted));
const unpaidTotal=computed(()=>unpaid.value.reduce((s,x)=>s+Math.max(0,Number(x.totalAmount)-Number(x.paidAmount||0)),0));
const isOverdue=d=>!!d&&String(d).slice(0,10)<dateKey(now.value);
const priority=computed(()=>[...unpaid.value].sort((a,b)=>String(a.dueDate).localeCompare(String(b.dueDate))||a.priorityLevel-b.priorityLevel).slice(0,3));
const pending=computed(()=>props.tasks.filter(x=>!x.isCompleted).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')));
const overdue=computed(()=>pending.value.filter(x=>isOverdue(x.dueDate)));
const todayEvents=computed(()=>props.events.filter(x=>x.startTime?.slice(0,10)===dateKey(now.value)).sort((a,b)=>a.startTime.localeCompare(b.startTime)));
const money=n=>hidden.value?'••••••':new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n||0);
const shortDate=d=>d?new Date(d).toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit'}):'Chưa đặt hạn';
const time=d=>d?new Date(d).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}):'';
</script>
